const { tavily } = require('@tavily/core');

// Initialize Tavily with API key from environment
const apiKey = process.env.TAVILY_API_KEY || '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';
const tvly = tavily({ apiKey });

// Get input from previous node
const topic = $input.item.json.inputText;
const title = $input.item.json.blogTitle;

// Research the topic
try {
  const research = await tvly.search(title + ' ' + topic, {
    searchDepth: 'advanced',
    maxResults: 5,
    includeAnswer: true
  });

  // Extract key information
  const sources = research.results.map(r => ({
    title: r.title,
    url: r.url,
    content: r.content.substring(0, 200) + '...'
  }));

  // Create enhanced prompt with research
  const enhancedContent = `Original Topic: ${title}\n\nOriginal Content: ${topic}\n\nResearch Summary: ${research.answer || 'No summary available'}\n\nKey Sources:\n${sources.map((s, i) => `${i + 1}. ${s.title}\n   ${s.content}`).join('\n\n')}`;

  return {
    json: {
      inputText: topic,
      blogTitle: title,
      author: $input.item.json.author,
      researchSummary: research.answer || 'No research summary',
      sources: sources,
      enhancedContent: enhancedContent
    }
  };

} catch (error) {
  // If Tavily fails, continue without research
  return {
    json: {
      inputText: topic,
      blogTitle: title,
      author: $input.item.json.author,
      researchSummary: 'Research unavailable',
      sources: [],
      enhancedContent: `Original Topic: ${title}\n\nOriginal Content: ${topic}`
    }
  };
}
